pub struct AlsCameraAnimationSet;

pub struct AlsSourceCameraPlugin;

impl Plugin for AlsSourceCameraPlugin {
    fn build(&self, app: &mut App) {
        app.add_systems(
            PostUpdate,
            initialize_components.before(AnimationGraphSet::PrePhysics),
        )
        .add_systems(
            PostUpdate,
            update_camera_animation
                .run_if(bevy::ecs::schedule::common_conditions::not(bevy::time::common_conditions::paused))
                .in_set(AlsCameraAnimationSet)
                .after(crate::extensions::post_physics_animation::PostPhysicsAnimationSet::Evaluate)
                .before(AnimationGraphSet::PostPhysics),
        )
        .add_systems(Update, (remove_orphaned_views, publish_player_view_yaw).chain().before(crate::als::view::AlsViewInputSet));
    }

fn publish_player_view_yaw(
    mut commands: Commands,
    mut characters: Query<(Entity, Option<&mut crate::als::view::AlsPlayerViewYaw>), With<crate::als::character::AlsCharacter>>,
    views: Query<(&Camera, Ref<GlobalTransform>, &AlsCharacterCamera), (With<Camera3d>, With<crate::als_camera::AlsCameraViewSource>)>,
) {
    for (character, current) in &mut characters {
        let yaw = views.iter().find_map(|(camera, transform, owner)| {
            (owner.character == character && camera.is_active && !transform.is_added())
                .then(|| transform.rotation().to_euler(EulerRot::YXZ).0).filter(|yaw| yaw.is_finite())
        });
        match (current, yaw) {
            (Some(mut current), Some(yaw)) => current.0 = yaw,
            (None, Some(yaw)) => { commands.entity(character).insert(crate::als::view::AlsPlayerViewYaw(yaw)); }
            (Some(_), None) => { commands.entity(character).remove::<crate::als::view::AlsPlayerViewYaw>(); }
            (None, None) => {}
        }
    }

pub fn apply_view_input_system(
    time: Res<Time<Real>>,
    virtual_time: Res<Time<Virtual>>,
    mut characters: Query<
        (
            &mut AlsViewYaw,
            &mut AlsViewPitch,
            &AlsInputCommand,
            Option<&AlsInputOverride>,
        ),
        With<AlsCharacter>,
    >,
) {
    if virtual_time.is_paused() { return; }
    let delta_seconds = if virtual_time.effective_speed() == 0.0 {
        time.delta_secs()
    } else {
        virtual_time.delta_secs() / virtual_time.effective_speed()
    };
    for (mut yaw, mut pitch, command, override_command) in &mut characters {
        let effective = override_command
            .map(|override_command| &override_command.0)
            .unwrap_or(command);
        let delta = look_delta_radians(effective, delta_seconds);
        yaw.0 -= delta.x;
        pitch.0 = clamp_pitch(pitch.0 - delta.y);
    }
}
